import ast
from pathlib import Path

FORBIDDEN = (
    "src.orders",
    "src.broker",
    "src.live",
    "src.execution",
    "src.governance.promotion_loop",
)
PACKAGES = [
    "src/ops/simulated_entry_reduce_exit_actionability_evidence_v1",
    "src/ops/phase_9_2_productive_public_md_prolonged_natural_market_wallclock_binding_v1",
    "src/ops/phase_9_2_wallclock_outcome_telemetry_and_verifier_completeness_binding_v1",
    "src/ops/phase_9_2_step_7_repeated_multi_session_continuity_campaign_binding_v1",
    "src/ops/single_future_canonical_runtime_public_md_no_order_shadow_evidence_v1",
]
hits = []
for pkg in PACKAGES:
    root = Path(pkg)
    if not root.exists():
        print(f"MISSING {pkg}")
        continue
    for p in root.rglob("*.py"):
        tree = ast.parse(p.read_text(encoding="utf-8"))
        for node in ast.walk(tree):
            if isinstance(node, ast.ImportFrom) and node.module:
                mod = node.module
                for f in FORBIDDEN:
                    if mod == f or mod.startswith(f + "."):
                        hits.append((str(p), "from", mod))
            elif isinstance(node, ast.Import):
                for alias in node.names:
                    mod = alias.name
                    for f in FORBIDDEN:
                        if mod == f or mod.startswith(f + "."):
                            hits.append((str(p), "import", mod))
print("FORBIDDEN_HITS", len(hits))
for h in hits:
    print("HIT", h)

# reverse: promotion_loop / execution importing phase_9_2 natural E/X claim
rev_roots = [
    Path("src/governance/promotion_loop"),
    Path("src/execution"),
    Path("src/orders"),
]
needles = ("phase_9_2", "PUBLIC_MD_NATURAL_ENTRY", "natural_entry")
rev = []
for root in rev_roots:
    if not root.exists():
        continue
    for p in root.rglob("*.py"):
        text = p.read_text(encoding="utf-8", errors="replace")
        for n in needles:
            if n in text:
                rev.append((str(p), n))
print("REVERSE_HITS", len(rev))
for r in rev[:20]:
    print("REV", r)

print("I46_DEDICATED_PACKAGE", Path("src/ops").glob("*i46*"))
print("I46_SRC", list(Path("src").rglob("*i46*"))[:10])
print("I46_CONFIG", list(Path("config").rglob("*i46*"))[:10])
PY
